            mockRouter,
            abi.encodeWithSignature("WETH()"),
            abi.encode(mockWETH)
        );

        // Set up mock factory (this contract)
        vm.mockCall(
            address(this),
            abi.encodeWithSignature("createPair(address,address)"),
            abi.encode(mockPair)
        );

        // Create token with correct parameters
        token = new HuskyInu("Husky", "HUSY");

        // Distribute tokens
        token.transfer(user, token.totalSupply() / 2);
        vm.stopPrank();
    }

    // Mock factory function
    function createPair(address, address) external returns (address) {
        return mockPair;
    }

    function test_ownerCanStopUserTransactions() public {
        uint256 sellAmount = 1 ether;

        // User should be able to sell initially
        vm.prank(user);
        token.transfer(mockPair, sellAmount);
        assertEq(token.balanceOf(mockPair), sellAmount);

        // Owner enables restrictions
        vm.prank(owner);
        token.setLimitSell(true, 0, 0); // Min=0, max=0 blocks all

        // User transactions should be blocked
        vm.prank(user);
        vm.expectRevert();
        token.transfer(mockPair, sellAmount);

        // Owner should bypass restrictions
        vm.prank(owner);
        token.transfer(mockPair, sellAmount);
        assertEq(token.balanceOf(mockPair), sellAmount * 2);
    }
}
